list_transactions.code:
var response = await client.Transactions.ListTransactionsAsync(
    new Dictionary<string, object?> { ["limit"] = 50, ["offset"] = 0 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var transaction in ((IReadOnlyList<object?>)body["transactions"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{transaction["transaction_no"]} {transaction["total_records"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

